import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), k = nextInt();
        long[] p = new long[n], gains = new long[n];
        for (int i = 0; i < n; i++) p[i] = nextLong();
        long base = 0;
        for (int i = 0; i < n; i++) {
            int b = nextInt();
            base += b != 0 ? p[i] : -p[i];
            gains[i] = b != 0 ? 0 : 2 * p[i];
        }
        long window = 0;
        for (int i = 0; i < k; i++) window += gains[i];
        long best = window;
        for (int i = k; i < n; i++) {
            window += gains[i] - gains[i - k];
            best = Math.max(best, window);
        }
        System.out.println(base + best);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := nextInt(), nextInt()
	p := make([]int, n)
	for i := range p {
		p[i] = nextInt()
	}
	gains := make([]int, n)
	base := 0
	for i := 0; i < n; i++ {
		if nextInt() != 0 {
			base += p[i]
		} else {
			base -= p[i]
			gains[i] = 2 * p[i] // turning a buy into a sell
		}
	}
	window := 0
	for i := 0; i < k; i++ {
		window += gains[i]
	}
	best := window
	for i := k; i < n; i++ {
		window += gains[i] - gains[i-k]
		best = max(best, window)
	}
	fmt.Println(base + best)
}
